import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BdlpXgFt.js";var i=JSON.parse(`{"title":"Sync Engine 架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/architecture.md","filePath":"zh-Hans/deep-dive/architecture.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/architecture.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="sync-engine-架构" tabindex="-1">Sync Engine 架构 <a class="header-anchor" href="#sync-engine-架构" aria-label="Permalink to “Sync Engine 架构”">​</a></h1><p>Sync Engine 由一组有序的内部模块组成。插件入口把这些模块交给 <a href="https://github.com/hesprs/synthkernel" target="_blank" rel="noreferrer">SynthKernel</a>，一个小的依赖注入与响应式运行时。结果是核心、UI 和动态加载的模块共享一个带类型的 context。</p><p>架构有三个边界：</p><ul><li><strong>内核边界</strong>：SynthKernel 构造模块、注入依赖，并把它们的公开 API 合并进一个 context。</li><li><strong>能力边界</strong>：Registrar 为文件系统、请求、同步决策、设置和其他扩展点暴露带类型的工厂和注册表。</li><li><strong>执行边界</strong>：同步作用于抽象的本地和远端文件系统。平台细节通过 <code>VaultRequest</code>、<code>Request</code>、中间件和文件系统包装器进入。</li></ul><p><a href="./sync">核心同步流程</a>、<a href="./request">请求抽象</a>和<a href="./file-system-wrappers">文件系统包装器</a>详细规定了这些执行边界。</p><h2 id="运行时生命周期" tabindex="-1">运行时生命周期 <a class="header-anchor" href="#运行时生命周期" aria-label="Permalink to “运行时生命周期”">​</a></h2><p><code>SyncEngine.onload()</code> 按以下顺序执行：</p><ol><li>加载设置。</li><li>为内部模块构造器创建 SynthKernel context。</li><li>注入已加载的 <code>settings</code> 对象，合并声明的 context 键：<code>settings</code>、<code>root</code>、<code>events</code> 和 <code>i18n</code>。</li><li>从本地模块目录加载已启用的外部模块。</li><li>添加插件设置页。</li><li>按插入顺序对每个内部和已加载模块调用 <code>start()</code>。</li></ol><p>卸载时，带 <code>dispose()</code> 的模块以相反顺序被调用。这让后启动的模块（例如 UI 和引导模块）能在它们使用的服务消失之前释放资源。</p><p>初始 context 还贡献了 Obsidian 原语，例如 <code>app</code>、<code>addCommand</code>、<code>addRibbonIcon</code>、<code>addStatusBarItem</code>、<code>registerEvent</code> 和 <code>saveSettings</code>。因此模块依赖的是小的结构化 context 契约，而不是自己去导入或寻找单例服务。</p><h2 id="synthkernel-依赖注入" tabindex="-1">SynthKernel 依赖注入 <a class="header-anchor" href="#synthkernel-依赖注入" aria-label="Permalink to “SynthKernel 依赖注入”">​</a></h2><p>每个模块是一个类构造器。SynthKernel 先构造内部构造器，然后从合并的 context 中解析构造器参数。模块通过属性发布能力，例如：</p><div class="language-ts" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">root </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { executeSync: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.executeSync };</span></span></code></pre></div><p>它还可以声明自己向合并键贡献的值的形状：</p><div class="language-ts" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">declare</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> readonly </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    syncStarted</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isCancelled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: Ref</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">boolean</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">trigger</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: string };</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>这些声明让最终的 <code>Context</code>、<code>Events</code>、<code>Settings</code> 和 <code>Translations</code> 类型从模块元组推导而来。它们不是第二个运行时注册表：SynthKernel 合并的是实际的 <code>root</code> 对象，并把选定的共享键注入模块实例。</p><p>context 也支持动态组合。<code>Extensibility</code> 验证并导入一个外部构造器，调用 SynthKernel 的 <code>__addModule__</code>，用 <code>__getModule__</code> 取回它的实例，并把构造器加入插件的生命周期集合。加载的模块接收与核心模块相同的合并 context。</p><p>SynthKernel 还提供跨模块边界使用的响应式原语。<code>Ref</code> 值携带活跃状态，例如空闲状态、取消和进度；<code>computed()</code> 推导展示状态；<code>hook()</code> 在弹窗 UI 中持有作用域内的订阅。例如，<code>Sync</code> 为每次运行创建一个取消 <code>Ref</code> 并通过事件总线发布，文件系统和请求层观察同一个引用。</p><h2 id="内部模块" tabindex="-1">内部模块 <a class="header-anchor" href="#内部模块" aria-label="Permalink to “内部模块”">​</a></h2><p><code>internalModules</code> 是 <code>packages/plugin/src/index.ts</code> 中的有序元组。顺序影响构造、启动和卸载。</p><ol><li><strong><code>EventBus</code></strong> 提供带类型的 <code>on</code>/<code>dispatch</code> 边界。它持有同步与一般日志，跟踪空闲状态，并记录任务结果。每个订阅返回一个取消订阅回调。</li><li><strong><code>I18n</code></strong> 为当前 Obsidian 语言选择翻译，注册核心和外部模块的资源，并提供带类型的字符串或 <code>DocumentFragment</code> 翻译函数。</li><li><strong><code>Storage</code></strong> 持有 Uni-KV 内存数据库和 IndexedDB 数据库。它暴露持久的记录存储、模块元数据存储和每个本地 / 远端配对的命名空间。</li><li><strong><code>Extensibility</code></strong> 发现模块元数据、验证来源与完整性、加载启用的 JavaScript 模块、持久化元数据，并管理启用、禁用、更新和卸载操作。它的安全与信任规则记录在<a href="./extensibility">扩展性契约</a>中。</li><li><strong><code>Setting</code></strong> 持有原生 Obsidian 设置页、嵌套的设置定义树、模块设置注册、标签和设置页刷新。</li><li><strong><code>Registrar</code></strong> 是能力与注册表层。它创建本地和远端文件系统、应用请求中间件和包装器、选择优化器和冲突解决器、按策略给状态分桶并分发给决策器、归约触发器条目，并向模块暴露注册函数。</li><li><strong><code>Sync</code></strong> 执行一次同步运行：初始化基础设施、遍历两侧、过滤状态、创建并转换任务、请求确认、执行任务并发布生命周期事件。见<a href="./sync">核心同步流程</a>。</li><li><strong><code>Observability</code></strong> 把事件转换为用户可见的状态、进度、通知、命令、侧边栏控件和导出的日志。进度弹窗消费它的响应式值。</li><li><strong><code>Scheduler</code></strong> 把手动、启动、定时、聚焦、实时和仓库变更触发器转换为排队的同步请求。它等待空闲状态、合并待处理请求、把批次的触发器归约到最高优先级的已注册条目，并让批次中的每个请求得到相同的结果。</li><li><strong><code>ProgressModal</code></strong> 处理进度显示、任务确认、删除确认、取消和失败任务详情。SynthKernel 的 <code>computed()</code> 值和 <code>hook()</code> 清理让弹窗状态限定在弹窗生命周期内。</li><li><strong><code>Bootstrap</code></strong> 通过 <code>Registrar</code> 安装内置的同步能力，并提供核心翻译。设置由 <code>Setting</code> 注册，它启动早于 <code>Bootstrap</code> 完成插件生命周期。</li></ol><p>依赖方向在构造器中刻意可见。例如，<code>Sync</code> 接收 <code>initializeSync</code>、<code>decideTasks</code> 和 <code>getConflictResolver</code>；它不知道是哪个后端、包装器或中间件提供了它们。<code>Bootstrap</code> 组装这些策略，而不改变同步算法。</p><h2 id="扩展性框架" tabindex="-1">扩展性框架 <a class="header-anchor" href="#扩展性框架" aria-label="Permalink to “扩展性框架”">​</a></h2><p>外部模块在运行时扩展同一个 context。<code>Extensibility</code> 验证并导入一个已批准的构造器，把它加入 SynthKernel，合并它的 <code>moduleSettings</code>，并把它加入 <code>allModules</code> 使其参与启动与卸载。卸载时调用 <code>dispose()</code>、移除构造器并发布 <code>moduleUnloaded</code>。</p><p>模块加载器同时是安全边界，因为模块是可执行代码。信任、完整性验证、启用、存储和运行时权限在<a href="./extensibility">扩展性契约</a>中规定；模块管理界面的行为见<a href="./module-management-page">模块管理界面</a>。</p><h2 id="注册模式" tabindex="-1">注册模式 <a class="header-anchor" href="#注册模式" aria-label="Permalink to “注册模式”">​</a></h2><p>大多数扩展点由 <code>Registrar.root</code> 以 <code>register*</code> 函数暴露。这个模式把注册与消费分开：</p><ul><li>集合型能力使用 <code>setRegister()</code>。它加入一个条目并返回 <code>() =&gt; registry.delete(entry)</code>。</li><li>ID 型能力使用 <code>mapRegister()</code>。它以 ID 存储条目并返回 <code>() =&gt; registry.delete(id)</code>。</li><li>CSS 注册追加一个样式元素并返回移除函数。</li><li><code>registerI18n()</code> 遵循语言选择规则，而不是 Registrar 注册表。</li></ul><p>例子包括 <code>registerRemoteFs</code>、<code>registerRemoteFsWrapper</code>、<code>registerRemoteRequestMiddleware</code>、<code>registerTrigger</code>、<code>registerDecider</code>、<code>registerConflictResolver</code>、<code>registerSetting</code> 和它们的本地对应版本。因此模块可以添加后端、策略、包装器或 UI 贡献，而不修改核心代码。</p><p>注册条目按各自的角色被消费：</p><ul><li><strong>工厂与 ID 映射</strong>：所选的远端后端和冲突解决器按设置中的 ID 查找；决策器在规划期间按策略名称查找。缺失的 ID 以明确的错误失败。</li><li><strong>包装器</strong>：请求和文件系统包装器按数字优先级分组，按优先级升序应用。同一优先级内，第一个返回替换值的包装器生效；返回 <code>undefined</code> 表示放弃当前值。</li><li><strong>首个匹配的流水线</strong>：优化器同样按优先级排序。第一个返回结果的条目为该操作提供实现。</li><li><strong>触发器</strong>：触发器条目以触发器名称为键。冲刷的同步批次被归约到最高优先级的条目，由它的选项定制这次运行。</li><li><strong>设置</strong>：设置定义树按优先级排序并合并进原生插件设置页。见<a href="./../development/settings-and-ui">设置与界面</a>。</li></ul><p>Bootstrap 用同样的 API 组装生产流水线。例如，取消、速率限制、重试、自定义请求头、内存控制、优化、context 缓存和非对称存储都是围绕基础请求与文件系统实现分层叠加的独立注册。它们的行为在<a href="./request-middleware">请求中间件</a>和<a href="./file-system-wrappers">文件系统包装器</a>中规定。</p><p>这让 Sync Engine 拥有稳定的核心算法，策略和传输层都可以替换。模块在启动时组合能力，通过带类型的 context API 消费它们，卸载时用同一个生命周期契约移除它们。</p>`,33)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};